{
  "schema_version": 1,
  "verdict": "needs-correction",
  "finding_class": "metadata-only",
  "rationale": "The answers are valid, but the national split is materially overstated. Indonesian officially recognizes \"tonsil\" as an equivalent of \"amandel,\" and Indonesian medical usage also uses \"tonsil.\" Malaysian Malay clearly uses \"tonsil.\" The distinction is therefore a preference/register contrast, not a clean different-word contrast. No false-friend contrast is supported.",
  "claim_reviews": [
    {
      "subject": "English cue and sense",
      "conclusion": "Correct. \"Tonsil\" denotes one of the two soft lymphoid organs at the back of the mouth/throat; the plural wording in the sense is compatible with the singular headword.",
      "material_risk": false,
      "evidence_refs": [
        "https://dictionary.cambridge.org/dictionary/english/tonsil",
        "https://www.cancer.gov/publications/dictionaries/cancer-terms/def/tonsil"
      ]
    },
    {
      "subject": "Indonesian answer \"amandel\"",
      "conclusion": "Correct and ordinary-looking Indonesian terminology for the target sense. Indonesian health guidance explicitly glosses amandel as tonsil.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.kemkes.go.id/app_asset/file_content_download/17012266166566a878c14712.29105429.pdf",
        "https://kamus.sabda.org/kamus/amandel"
      ]
    },
    {
      "subject": "Indonesian overlap with \"tonsil\"",
      "conclusion": "Material overlap exists. \"Tonsil\" is recorded as an Indonesian equivalent of \"amandel\" and is used in Indonesian medical terminology, so it should not be presented as exclusively Malaysian.",
      "material_risk": true,
      "evidence_refs": [
        "https://kbbi.cari.co/tonsil",
        "https://www.kemkes.go.id/app_asset/file_content_download/17012266166566a878c14712.29105429.pdf"
      ],
      "evidence_limitation": "The reviewed sources establish acceptance and medical usage but do not provide a comparable corpus-based frequency measure for everyday Indonesian versus Malaysian usage."
    },
    {
      "subject": "Malaysian Malay answer \"tonsil\"",
      "conclusion": "Correct and directly supported by the Malaysian DBP reference dictionary for the target throat tissue.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=54140&keyword=tonsil"
      ]
    },
    {
      "subject": "Final relation \"different-common-word\"",
      "conclusion": "Needs revision or qualification. The forms differ in apparent everyday preference, but they are not cleanly different across the national varieties because Indonesian accepts and uses \"tonsil.\"",
      "material_risk": true,
      "evidence_refs": [
        "https://kbbi.cari.co/tonsil",
        "https://www.kemkes.go.id/app_asset/file_content_download/17012266166566a878c14712.29105429.pdf",
        "https://prpm.dbp.gov.my/Cari1?d=54140&keyword=tonsil"
      ]
    },
    {
      "subject": "False-friend contrast",
      "conclusion": "No valid false-friend contrast is present. \"Amandel\" and \"tonsil\" refer to the same anatomical concept in the reviewed sources; the card's empty contrast field is preferable to inventing one.",
      "material_risk": false,
      "evidence_refs": [
        "https://kamus.sabda.org/kamus/amandel",
        "https://prpm.dbp.gov.my/Cari1?d=54140&keyword=tonsil"
      ]
    }
  ]
}
